USE `guniversal_dbp`;
SET NAMES utf8mb4;
INSERT INTO ajuda_transacoes(transacao,titulo_pt,titulo_en,titulo_es,texto_pt,texto_en,texto_es)
VALUES(
'ia_potenciais_resultado','Ajuda - Resultado da analise de IA','Help - AI analysis result','Ayuda - Resultado del analisis de IA',
'<p>Esta tela apresenta o resultado da analise solicitada para um requisito legal.</p><h2>Tabela de resultados</h2><p>Cada linha representa uma sugestao de potencial identificada pela IA.</p><ul><li><strong>Tipo:</strong> classifica a sugestao como Controle, Influencia, Licenca, Monitoramento, Treinamento ou Infraestrutura.</li><li><strong>Titulo:</strong> nome resumido da acao sugerida.</li><li><strong>Descricao:</strong> explica a acao que pode ser avaliada pela empresa.</li><li><strong>Justificativa:</strong> mostra por que a IA relacionou a sugestao ao requisito legal.</li><li><strong>Confianca:</strong> indica o nivel de seguranca estimado pela IA. De 0 a 39 e baixa, de 40 a 69 e moderada, de 70 a 89 e boa e de 90 a 100 e alta. Esse valor nao e percentual de atendimento e nao substitui a analise humana.</li></ul><h2>Status</h2><p>Aguardando processamento e Em processamento indicam que a solicitacao ainda esta na fila. Concluida indica que o resultado foi gerado. Erro indica que o processamento nao terminou corretamente.</p><h2>Aprovacao e rejeicao</h2><p>O ADMINISTRADOR e o ADM_DA_EMPRESA podem aprovar ou rejeitar sugestoes. O GESTOR pode somente consultar. A aprovacao nao e feita automaticamente pela IA.</p>',
'<p>This screen presents the result of the analysis requested for a legal requirement.</p><h2>Results table</h2><p>Each row represents a potential action suggested by the AI.</p><ul><li><strong>Type:</strong> classifies the suggestion as Control, Influence, License, Monitoring, Training or Infrastructure.</li><li><strong>Title:</strong> short name of the suggested action.</li><li><strong>Description:</strong> explains the action to be assessed by the company.</li><li><strong>Justification:</strong> explains why the AI related the suggestion to the legal requirement.</li><li><strong>Confidence:</strong> estimated confidence level. 0 to 39 is low, 40 to 69 moderate, 70 to 89 good and 90 to 100 high. It is not a compliance percentage and does not replace human review.</li></ul><h2>Status</h2><p>Waiting for processing and Processing mean that the request is still in the queue. Completed means that the result was generated. Error means that processing failed.</p><h2>Approve and reject</h2><p>ADMINISTRATOR and ADM_DA_EMPRESA can approve or reject suggestions. GESTOR can only view them. Approval is never performed automatically by the AI.</p>',
'<p>Esta pantalla muestra el resultado del analisis solicitado para un requisito legal.</p><h2>Tabla de resultados</h2><p>Cada fila representa una accion potencial sugerida por la IA.</p><ul><li><strong>Tipo:</strong> clasifica la sugerencia como Control, Influencia, Licencia, Monitoreo, Capacitacion o Infraestructura.</li><li><strong>Titulo:</strong> nombre resumido de la accion sugerida.</li><li><strong>Descripcion:</strong> explica la accion que debe ser evaluada por la empresa.</li><li><strong>Justificacion:</strong> explica por que la IA relaciono la sugerencia con el requisito legal.</li><li><strong>Confianza:</strong> nivel estimado de seguridad. De 0 a 39 es baja, de 40 a 69 moderada, de 70 a 89 buena y de 90 a 100 alta. No es un porcentaje de cumplimiento ni sustituye la revision humana.</li></ul><h2>Estado</h2><p>Esperando procesamiento y Procesando indican que la solicitud sigue en la cola. Completada indica que el resultado fue generado. Error indica que el procesamiento fallo.</p><h2>Aprobar y rechazar</h2><p>ADMINISTRADOR y ADM_DA_EMPRESA pueden aprobar o rechazar sugerencias. GESTOR solo puede consultarlas. La aprobacion nunca es automatica.</p>')
ON DUPLICATE KEY UPDATE titulo_pt=VALUES(titulo_pt),titulo_en=VALUES(titulo_en),titulo_es=VALUES(titulo_es),texto_pt=VALUES(texto_pt),texto_en=VALUES(texto_en),texto_es=VALUES(texto_es),ativo=1;
